package dev.pathland.markdown;

import dev.pathland.view.core.AttributedString;
import dev.pathland.view.core.LinkRun;
import dev.pathland.view.core.StyleRun;
import dev.pathland.view.core.TextAttribute;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import org.commonmark.ext.gfm.strikethrough.Strikethrough;
import org.commonmark.ext.gfm.strikethrough.StrikethroughExtension;
import org.commonmark.node.Code;
import org.commonmark.node.Emphasis;
import org.commonmark.node.HardLineBreak;
import org.commonmark.node.HtmlInline;
import org.commonmark.node.Image;
import org.commonmark.node.Link;
import org.commonmark.node.Node;
import org.commonmark.node.Paragraph;
import org.commonmark.node.SoftLineBreak;
import org.commonmark.node.StrongEmphasis;
import org.commonmark.node.Text;
import org.commonmark.parser.Parser;

/**
 * Pathland's shared inline Markdown parser — now backed by the same
 * commonmark-java engine the docs renderer uses.
 *
 * <p>This class stays deliberately **inline-only** (the public contract of
 * {@code Text(...)}): it parses the inline subset — {@code **bold**} /
 * {@code __bold__}, {@code *italic*} / {@code _italic_}, {@code `code`},
 * {@code ~~strikethrough~~}, {@code [label](url)}, and backslash escapes — into
 * a view-core {@link AttributedString}. Block constructs are not rendered here:
 * if the input contains a heading/list/code-fence/etc. the whole value falls
 * back to plain text, so headings and list markers remain literal in a text
 * view. The docs module uses the full block parser.
 *
 * <p>Ranges are UTF-8 byte offsets (the wire convention).
 */
public final class Markdown {

    private static final int CACHE_LIMIT = 512;
    private static final Map<String, AttributedString> CACHE =
            Collections.synchronizedMap(new LinkedHashMap<>(64, 0.75f, true) {
                @Override
                protected boolean removeEldestEntry(Map.Entry<String, AttributedString> eldest) {
                    return size() > CACHE_LIMIT;
                }
            });

    private static final Parser PARSER = Parser.builder()
            .extensions(List.of(StrikethroughExtension.create()))
            .build();

    private Markdown() {}

    /**
     * Whether the parser is available. Always {@code true} — the parser is pure
     * JVM code.
     */
    public static boolean isAvailable() {
        return true;
    }

    /** Parse inline Markdown into an attributed string. */
    public static AttributedString parse(String text) {
        Node document = PARSER.parse(text);
        if (!containsOnlyParagraphs(document)) {
            // `Text` is inline-only. Keep block syntax literal rather than
            // silently turning a heading/list/fence into styled text.
            return AttributedString.plain(text);
        }
        Output out = new Output();
        boolean first = true;
        for (Node block = document.getFirstChild(); block != null; block = block.getNext()) {
            if (!first) {
                out.appendString("\n\n");
            }
            first = false;
            inlineChildren(block, out);
        }
        return AttributedString.of(out.text.toString(), out.runs, out.links);
    }

    /**
     * Whether {@code text} contains any inline-Markdown marker. A cheap scan
     * lets plain strings skip the parser entirely.
     */
    public static boolean containsMarkdownSyntax(String text) {
        for (int i = 0; i < text.length(); i++) {
            switch (text.charAt(i)) {
                case '*':
                case '_':
                case '~':
                case '`':
                case '[':
                case '\\':
                    return true;
                default:
                    break;
            }
        }
        return false;
    }

    /**
     * Parse inline Markdown, falling back to plain text when the input has no
     * Markdown markers. Results are cached (bounded) so static literals and
     * repeated values parse once.
     */
    public static AttributedString parseOrPlain(String text) {
        if (!containsMarkdownSyntax(text)) {
            return AttributedString.plain(text);
        }
        AttributedString cached = CACHE.get(text);
        AttributedString cached = CACHE.get(text);
        if (cached != null) {
            return cached;
        }
        AttributedString value;
        try {
            value = parse(text);
        } catch (RuntimeException e) {
            // Degrade to literal text rather than failing the whole view.
            value = AttributedString.plain(text);
        }
        CACHE.put(text, value);
        return value;
    }

    private static boolean containsOnlyParagraphs(Node document) {
        for (Node block = document.getFirstChild(); block != null; block = block.getNext()) {
            if (!(block instanceof Paragraph)) {
                return false;
            }
        }
        return true;
    }

    private static void inlineChildren(Node parent, Output out) {
        for (Node child = parent.getFirstChild(); child != null; child = child.getNext()) {
            inline(child, out);
        }
    }

    private static void inline(Node node, Output out) {
        if (node instanceof Text text) {
            out.appendString(text.getLiteral());
            return;
        }
        if (node instanceof Emphasis) {
            int start = out.bytes;
            inlineChildren(node, out);
            out.runs.add(new StyleRun(start, out.bytes, List.of(TextAttribute.italic())));
            return;
        }
        if (node instanceof StrongEmphasis) {
            int start = out.bytes;
            inlineChildren(node, out);
            out.runs.add(new StyleRun(start, out.bytes, List.of(TextAttribute.fontWeight(700f))));
            return;
        }
        if (node instanceof Strikethrough) {
            int start = out.bytes;
            inlineChildren(node, out);
            out.runs.add(new StyleRun(start, out.bytes, List.of(TextAttribute.strikethrough(true))));
            return;
        }
        if (node instanceof Code code) {
            int start = out.bytes;
            out.appendString(code.getLiteral());
            out.runs.add(new StyleRun(start, out.bytes, List.of(TextAttribute.fontDesign(3))));
            return;
        }
        if (node instanceof Link link) {
            int start = out.bytes;
            inlineChildren(node, out);
            out.links.add(new LinkRun(start, out.bytes, link.getDestination()));
            return;
        }
        if (node instanceof Image) {
            // AttributedString has no inline image run; keep the alt text.
            inlineChildren(node, out);
            return;
        }
        if (node instanceof SoftLineBreak || node instanceof HardLineBreak) {
            out.appendChar('\n');
            return;
        }
        if (node instanceof HtmlInline html) {
            // Raw HTML is not interpreted in Text; keep it literal.
            out.appendString(html.getLiteral());
            return;
        }
        if (node.getFirstChild() != null) {
            inlineChildren(node, out);
        }
    }

    /** The accumulated output plus its running UTF-8 byte length. */
    private static final class Output {
        final StringBuilder text = new StringBuilder();
        final List<StyleRun> runs = new ArrayList<>();
        final List<LinkRun> links = new ArrayList<>();
        int bytes;

        void appendChar(char value) {
            text.append(value);
            bytes += utf8Length(value);
        }

        void appendString(String value) {
            text.append(value);
            bytes += value.getBytes(StandardCharsets.UTF_8).length;
        }
    }

    private static int utf8Length(int codePoint) {
        if (codePoint < 0x80) {
            return 1;
        }
        if (codePoint < 0x800) {
            return 2;
        }
        if (codePoint < 0x10000) {
            return 3;
        }
        return 4;
    }
}

