/** The per-session root: binds the router to the host's active-path signal. */
private class DocsRoot(
    private val repository: DocsRepository,
    private val componentDocs: List<ComponentDoc>,
    private val componentByRoute: Map<String, ComponentDoc>,
    private val componentsIndex: DocsPage,
) : View {
    private var router: Router? = null

    override fun renderNode(env: Environment): PathlandNode {
        val pages = repository.pages
        val docsHome = pages.first().route
        val activePath = Environment.value(Platform.ACTIVE_PATH)
        val resolved = router ?: navigator(activePath) {
            route("/", MarketingPage(docsHome))
            for (page in pages) {
                val component = componentByRoute[page.route]
                when {
                    page.route == componentsIndex.route -> route(
                        page.route,
                        ComponentDocsIndexPage(page, componentDocs, repository),
                    )
                    component != null -> route(page.route, ComponentDocsPage(component, repository))
                    else -> route(page.route, DocsLayout(page, repository))
                }
            }
            fallback(NotFoundPage())
        }.also { router = it }
        return NavigationStack(resolved).renderNode(env)
    }
}

