/** One documented protocol/DSL property. */
data class DocProperty(
    val name: String,
    val type: String,
    val description: String,
)

/** A code example on a component page. */
data class DocExample(
    val title: String,
    val description: String = "",
    val code: String,
)

/**
 * SwiftUI-style component documentation: a summary, overview, declaration,
 * optional live preview, examples, parameters, availability, notes, and links.
 */
data class ComponentDoc(
    val name: String,
    val slug: String,
    val summary: String,
    val declaration: String,
    val overview: String = "",
    val properties: List<DocProperty> = emptyList(),
    val examples: List<DocExample> = emptyList(),
    val notes: List<String> = emptyList(),
    val platforms: List<String> = listOf("Web", "GTK", "Qt"),
    val related: List<String> = emptyList(),
    val demo: (() -> View)? = null,
) {
    val route: String get() = "/docs/components/$slug"

    fun toPage(order: Int): DocsPage = DocsPage(
        sourcePath = "components/$slug.md",
        route = route,
        title = name,
        description = summary,
        section = "Components",
        order = order,
        markdown = toMarkdown(),
    )

    fun toc(): List<MarkdownHeading> = buildList {
        if (overview.isNotBlank()) add(MarkdownHeading(2, "overview", "Overview"))
        if (demo != null) add(MarkdownHeading(2, "preview", "Preview"))
        add(MarkdownHeading(2, "declaration", "Declaration"))
        if (examples.isNotEmpty()) add(MarkdownHeading(2, "examples", "Examples"))
        if (properties.isNotEmpty()) add(MarkdownHeading(2, "parameters", "Parameters"))
        if (platforms.isNotEmpty()) add(MarkdownHeading(2, "availability", "Availability"))
        if (notes.isNotEmpty()) add(MarkdownHeading(2, "notes", "Notes"))
        if (related.isNotEmpty()) add(MarkdownHeading(2, "see-also", "See Also"))
    }

    fun toMarkdown(): String = buildString {
        appendLine("# $name")
        appendLine()
        appendLine(summary)
        if (overview.isNotBlank()) {
            appendLine()
            appendLine("## Overview")
            appendLine()
            appendLine(overview)
        }
        appendLine()
        appendLine("## Declaration")
        appendLine()
        appendLine("```kotlin")
        appendLine(declaration)
        appendLine("```")
        if (examples.isNotEmpty()) {
            appendLine()
            appendLine("## Examples")
            for (example in examples) {
                appendLine()
                appendLine("### ${example.title}")
                if (example.description.isNotBlank()) {
                    appendLine()
                    appendLine(example.description)
                }
                appendLine()
                appendLine("```kotlin")
                appendLine(example.code)
                appendLine("```")
            }
        }
        if (properties.isNotEmpty()) {
            appendLine()
            appendLine("## Parameters")
            appendLine()
            appendLine("| Name | Type | Description |")
            appendLine("|---|---|---|")
            for (property in properties) {
                appendLine("| `${property.name}` | `${property.type}` | ${property.description} |")
            }
        }
        if (platforms.isNotEmpty()) {
            appendLine()
            appendLine("## Availability")
            appendLine()
            appendLine(platforms.joinToString(" · "))
        }
        if (related.isNotEmpty()) {
            appendLine()
            appendLine("## See Also")
            for (slug in related) {
                appendLine("- [$slug](/docs/components/$slug)")
            }
        }
    }
}

/** A SwiftUI-docs-style page for one component. */
@JvmOverloads
fun ComponentDocsPage(
    doc: ComponentDoc,
    repository: DocsRepository,
    siteTitle: String = "Pathland",
    homeRoute: String = "/",
): View = DocsLayout(
    page = doc.toPage(order = 100),
    repository = repository,
    siteTitle = siteTitle,
    homeRoute = homeRoute,
    tocOverride = doc.toc(),
) {
    VStack(alignment = HorizontalAlignment.LEADING, spacing = 24f) {
        Text(doc.summary)
            .fontSize(18f)
            .foregroundStyle(Color.token("color.text.secondary"))

        if (doc.overview.isNotBlank()) {
            DocSection("Overview", "overview")
            Markdown(doc.overview)
        }

        if (doc.demo != null) {
            DocSection("Preview", "preview")
            PreviewCard(doc.demo)
        }

        DocSection("Declaration", "declaration")
        CodeBlock(doc.declaration, "kotlin")

        if (doc.examples.isNotEmpty()) {
            DocSection("Examples", "examples")
            for (example in doc.examples) {
                VStack(alignment = HorizontalAlignment.LEADING, spacing = 8f) {
                    Text(example.title).font(Font.headline())
                    if (example.description.isNotBlank()) {
                        Text(example.description)
                            .foregroundStyle(Color.token("color.text.secondary"))
                    }
                    CodeBlock(example.code, "kotlin")
                }
            }
        }

        if (doc.properties.isNotEmpty()) {
            DocSection("Parameters", "parameters")
            PropertyTable(doc.properties)
        }

        if (doc.platforms.isNotEmpty()) {
            DocSection("Availability", "availability")
            HStack(spacing = 8f) {
                for (platform in doc.platforms) {
                    Text(platform)
                        .fontSize(11f)
                        .fontWeight(FontWeight.SEMIBOLD)
                        .padding(top = 3f, right = 8f, bottom = 3f, left = 8f)
                        .background(Color.token("color.surface"))
                        .border(Color.token("color.border"), 1f, 6f)
                }
            }
        }

        if (doc.notes.isNotEmpty()) {
            DocSection("Notes", "notes")
            VStack(alignment = HorizontalAlignment.LEADING, spacing = 6f) {
                for (note in doc.notes) {
                    Text("• $note")
                        .foregroundStyle(Color.token("color.text.secondary"))
                }
            }
        }

        if (doc.related.isNotEmpty()) {
            DocSection("See Also", "see-also")
            HStack(spacing = 12f) {
                for (slug in doc.related) {
                    Text("[${humanize(slug)}](/docs/components/$slug)")
                }
            }
        }
    }
}

/** A SwiftUI-docs-style index of every component. */
@JvmOverloads
fun ComponentDocsIndexPage(
    page: DocsPage,
    docs: List<ComponentDoc>,
    repository: DocsRepository,
    siteTitle: String = "Pathland",
    homeRoute: String = "/",
): View = DocsLayout(
    page = page,
    repository = repository,
    siteTitle = siteTitle,
    homeRoute = homeRoute,
    tocOverride = emptyList(),
) {
    VStack(alignment = HorizontalAlignment.LEADING, spacing = 16f) {
        Text(
            "Every Pathland primitive, container, and control, documented in the " +
                "same shape: overview, declaration, live preview, examples, and parameters.",
        ).fontSize(18f).foregroundStyle(Color.token("color.text.secondary"))

        Grid(columns = 3, spacing = 16f) {
            for (doc in docs) {
                Button(action = {}) {
                    VStack(alignment = HorizontalAlignment.LEADING, spacing = 6f) {
                        Text(doc.name).font(Font.headline())
                        Text(doc.summary)
                            .fontSize(13f)
                            .foregroundStyle(Color.token("color.text.secondary"))
                    }
                    .padding(16f)
                }
                .buttonStyle(plainButtonStyle())
                .background(Color.token("color.surface"))
                .border(Color.token("color.border"), 1f, 10f)
                .navigate(doc.route)
            }
        }
    }
}

private fun DocSection(title: String, id: String) {
    Text(title).font(Font.title2()).anchor(id)
}

private fun PreviewCard(demo: () -> View) {
    VStack(alignment = HorizontalAlignment.LEADING, spacing = 12f) {
        Text("LIVE PREVIEW")
            .fontSize(10f)
            .fontWeight(FontWeight.SEMIBOLD)
            .foregroundStyle(Color.token("color.text.secondary"))
        demo()
    }
    .padding(20f)
    .background(Color.token("color.surface"))
    .border(Color.token("color.border"), 1f, 10f)
}

private fun PropertyTable(properties: List<DocProperty>) {
    ScrollView(axis = ScrollAxis.HORIZONTAL) {
        Grid(columns = 3, spacing = 0f) {
            GridRow {
                HeaderCell("Name")
                HeaderCell("Type")
                HeaderCell("Description")
            }
            for (property in properties) {
                GridRow {
                    BodyCell(property.name, monospaced = true, width = 150f)
                    BodyCell(property.type, monospaced = true, width = 110f)
                    BodyCell(property.description)
                }
            }
        }
    }
}

private fun HeaderCell(text: String) {
    Text(text)
        .fontSize(12f)
        .fontWeight(FontWeight.SEMIBOLD)
        .padding(8f)
        .background(Color.token("color.surface"))
        .border(Color.token("color.border"), 1f)
}

private fun BodyCell(text: String, monospaced: Boolean = false, width: Float? = null) {
    var view: View = Text(text, markdown = false)
        .fontSize(13f)
        .multilineTextAlignment(TextAlignment.LEADING)
        .padding(8f)
        .border(Color.token("color.border"), 1f)
    if (monospaced) view = view.fontDesign(FontDesign.MONOSPACED).fontSize(12f)
    if (width != null) view = view.frame(width = width)
    view
}

private fun humanize(slug: String): String =
    slug.split('-', '_').joinToString(" ") { token ->
        token.replaceFirstChar { it.uppercaseChar() }
    }

package dev.pathland.docs

import java.util.Locale

/** One documentation page loaded from a Markdown resource. */
data class DocsPage(
    val sourcePath: String,
    val route: String,
    val title: String,
    val description: String? = null,
    val section: String? = null,
    val order: Int = 1000,
    val draft: Boolean = false,
    val updated: String? = null,
    val image: String? = null,
    val markdown: String,
) {
    companion object {
        private val FRONT_MATTER = Regex("^\\uFEFF?---\\s*\\r?\\n(.*?)\\r?\\n---\\s*\\r?\\n?", RegexOption.DOT_MATCHES_ALL)

        /**
         * Parse one `.md` resource: YAML-ish front matter (flat `key: value`
         * entries — enough for docs metadata; no YAML dependency) plus the body.
         */
        @JvmStatic
        @JvmOverloads
        fun fromMarkdown(
            sourcePath: String,
            raw: String,
            routePrefix: String = "/docs",
        ): DocsPage {
            val match = FRONT_MATTER.find(raw)
            val fields = LinkedHashMap<String, String>()
            val body = if (match != null) {
                parseFields(match.groupValues[1], fields)
                raw.substring(match.range.last + 1)
            } else {
                raw
            }
            val fallbackTitle = firstHeading(body) ?: humanize(fileName(sourcePath))
            val route = fields["route"]?.takeIf { it.isNotBlank() } ?: deriveRoute(sourcePath, routePrefix)
            return DocsPage(
                sourcePath = sourcePath,
                route = normalizeRoute(route),
                title = fields["title"]?.takeIf { it.isNotBlank() } ?: fallbackTitle,
                description = fields["description"]?.takeIf { it.isNotBlank() } ?: firstParagraph(body),
                section = fields["section"]?.takeIf { it.isNotBlank() },
                order = fields["order"]?.trim()?.toIntOrNull() ?: 1000,
                draft = fields["draft"]?.trim()?.equals("true", ignoreCase = true) == true,
                updated = fields["updated"]?.takeIf { it.isNotBlank() },
                image = fields["image"]?.takeIf { it.isNotBlank() },
                markdown = body.trimStart('\n'),
            )
        }

        private fun parseFields(text: String, out: MutableMap<String, String>) {
            for (line in text.lineSequence()) {
                val trimmed = line.trim()
                if (trimmed.isEmpty() || trimmed.startsWith("#")) continue
                val colon = trimmed.indexOf(':')
                if (colon <= 0) continue
                val key = trimmed.substring(0, colon).trim().lowercase(Locale.ROOT)
                var value = trimmed.substring(colon + 1).trim()
                if (value.length >= 2 &&
                    ((value.startsWith("\"") && value.endsWith("\"")) ||
                        (value.startsWith("'") && value.endsWith("'")))
                ) {
                    value = value.substring(1, value.length - 1)
                }
                out[key] = value
            }
        }

        private fun fileName(path: String): String =
            path.substringAfterLast('/').substringBeforeLast('.')

        private fun firstHeading(markdown: String): String? =
            markdown.lineSequence().firstOrNull { it.trimStart().startsWith("# ") }
                ?.trimStart()?.removePrefix("# ")?.trim()?.takeIf { it.isNotEmpty() }

        private fun firstParagraph(markdown: String): String? =
            markdown.lineSequence()
                .map { it.trim() }
                .firstOrNull { it.isNotEmpty() && !it.startsWith("#") && !it.startsWith("```") }
                ?.replace(Regex("[*_`~\\[\\]]"), "")
                ?.takeIf { it.isNotEmpty() }

        private fun humanize(name: String): String =
            name.split('-', '_')
                .filter { it.isNotBlank() }
                .joinToString(" ") { token -> token.replaceFirstChar { it.uppercaseChar() } }

        /** `docs/guides/install.md` or `content/docs/guides/index.md` → `/docs/guides/install`. */
        @JvmStatic
        @JvmOverloads
        fun deriveRoute(sourcePath: String, routePrefix: String = "/docs"): String {
            val normalized = sourcePath.replace('\\', '/')
            var path = normalized
            listOf("content/docs/", "docs/", "content/").forEach { prefix ->
                if (path.startsWith(prefix)) path = path.removePrefix(prefix)
            }
            path = path.removeSuffix(".md").removeSuffix(".markdown")
            val segments = path.split('/').filter { it.isNotBlank() }
            val clean = buildList {
                for (segment in segments) {
                    if (segment == "index" || segment == "README") {
                        if (isEmpty()) add("")
                        continue
                    }
                    add(slug(segment))
                }
            }.filter { it.isNotEmpty() }
            val suffix = clean.joinToString("/")
            return when {
                suffix.isEmpty() -> routePrefix
                else -> routePrefix.trimEnd('/') + "/" + suffix
            }
        }

        private fun slug(value: String): String =
            value.trim().lowercase(Locale.ROOT)
                .replace(Regex("[^a-z0-9]+"), "-")
                .trim('-')

        private fun normalizeRoute(value: String): String {
            val trimmed = value.trim()
            val withSlash = if (trimmed.startsWith('/')) trimmed else "/$trimmed"
            return if (withSlash.length > 1) withSlash.trimEnd('/') else withSlash
        }
    }
}

/** A navigation group (section) containing pages in display order. */
data class DocsSection(
    val title: String?,
    val pages: List<DocsPage>,
)

