        }
    }

    private fun page(doc: ComponentDoc, order: Int): String = buildString {
        appendLine("---")
        appendLine("title: ${doc.name}")
        appendLine("description: ${oneLine(doc.summary)}")
        appendLine("section: Components")
        appendLine("order: $order")
        appendLine("---")
