        appendLine("# ${doc.name}")
        appendLine()
        appendLine(doc.summary)
        if (doc.overview.isNotBlank()) {
            appendLine()
            appendLine("## Overview")
            appendLine()
            appendLine(doc.overview)
        }
        appendLine()
        appendLine("## Declaration")
        appendLine()
        appendLine("```kotlin")
        appendLine(doc.declaration)
        appendLine("```")
        if (doc.examples.isNotEmpty()) {
            appendLine()
            appendLine("## Examples")
            doc.examples.forEach { example ->
                appendLine()
                appendLine("### ${example.title}")
                if (example.description.isNotBlank()) {
                    appendLine()
                    appendLine(example.description)
                }
                appendLine()
                appendLine("```kotlin")
                appendLine(example.code)
                appendLine("```")
            }
        }
        if (doc.properties.isNotEmpty()) {
            appendLine()
            appendLine("## Parameters")
            appendLine()
            appendLine("| Name | Type | Description |")
            appendLine("|---|---|---|")
            doc.properties.forEach { property ->
                appendLine("| `${property.name}` | `${property.type}` | ${property.description} |")
            }
        }
        if (doc.platforms.isNotEmpty()) {
            appendLine()
            appendLine("## Availability")
            appendLine()
            appendLine(doc.platforms.joinToString(" · "))
        }
        if (doc.notes.isNotEmpty()) {
            appendLine()
            appendLine("## Notes")
            doc.notes.forEach { appendLine("- $it") }
        }
        if (doc.related.isNotEmpty()) {
            appendLine()
            appendLine("## See Also")
            doc.related.forEach { slug -> appendLine("- [${humanize(slug)}]($slug.md)") }
        }
    }

    private fun oneLine(value: String): String =
        value.replace('\n', ' ').replace('\r', ' ').trim()

    private fun humanize(slug: String): String =
        slug.split('-', '_').joinToString(" ") { token -> token.replaceFirstChar { it.uppercaseChar() } }
}
